import{_ as a,o as l,c as i,a5 as o}from"./chunks/framework.BF53ZjCA.js";const u=JSON.parse('{"title":"GemAtlas 欧泊首页 Hero 设计规范","description":"","frontmatter":{},"headers":[],"relativePath":"zh/superpowers/specs/2026-09-07-opal-homepage-hero-design.md","filePath":"zh/superpowers/specs/2026-09-07-opal-homepage-hero-design.md","lastUpdated":1789155237000}'),t={name:"zh/superpowers/specs/2026-09-07-opal-homepage-hero-design.md"};function d(r,e,c,n,h,s){return l(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="gematlas-欧泊首页-hero-设计规范" tabindex="-1">GemAtlas 欧泊首页 Hero 设计规范 <a class="header-anchor" href="#gematlas-欧泊首页-hero-设计规范" aria-label="Permalink to &quot;GemAtlas 欧泊首页 Hero 设计规范&quot;">​</a></h1><h2 id="状态" tabindex="-1">状态 <a class="header-anchor" href="#状态" aria-label="Permalink to &quot;状态&quot;">​</a></h2><ul><li>状态：实现完成，等待用户体验复核。</li><li>日期：2026-09-07</li><li>范围：独立首页 Hero 与进入知识百科主页的入口体验。</li><li>技术约束：GemAtlas 当前使用 VitePress、Vue 3 与 TypeScript，不迁移到 React、Tailwind 或 shadcn。</li></ul><h2 id="目标" tabindex="-1">目标 <a class="header-anchor" href="#目标" aria-label="Permalink to &quot;目标&quot;">​</a></h2><p>把首页第一屏做成“从一束光，认识一颗宝石”的沉浸式入口：访客先看到暗场中的欧泊成品，再看到全屏光线缓慢扫过，欧泊变彩逐渐显现，最后通过顶部模块入口进入五个知识板块。欧泊的成因、变彩原理、切割和鉴定细节仍由现有知识页面承载。</p><h2 id="已确认方向" tabindex="-1">已确认方向 <a class="header-anchor" href="#已确认方向" aria-label="Permalink to &quot;已确认方向&quot;">​</a></h2><p>采用 A 方向的叙事骨架：展柜正面、欧泊成品微距、主体占据主要视觉重量。候选素材为 Wikimedia Commons 的 Rainbow Shield 欧泊吊坠照片（2807×3358，作者 Dpulitzer，CC BY-SA 4.0）。正式使用时必须保留本地副本，并在 <code>docs/image-credits.md</code> 记录作者、来源、许可和处理方式。</p><ul><li>保留欧泊、金属镶嵌和真实反光，不用生成式宝石替换主体。</li><li>通过微距裁切和轻微镜头推进让成品进入画面主体，不再固定在页面下方。</li><li>标题始终位于视觉中心，利用主体偏移和暗部留白保证可读性。</li><li>视觉层级保持克制：中央标题为唯一主叙事锚点，欧泊成品右侧偏置并通过边缘淡出避免侵入标题安全区。</li><li>顶部使用玻璃胶囊模块键：<code>01 分类</code>、<code>02 鉴定</code>、<code>03 切割</code>、<code>04 分级</code>、<code>05 画廊</code>。</li><li>移动端允许模块胶囊横向滚动，每个入口触控区域不小于 44×44px。</li></ul><h2 id="动效时间线" tabindex="-1">动效时间线 <a class="header-anchor" href="#动效时间线" aria-label="Permalink to &quot;动效时间线&quot;">​</a></h2><p>动效目的是解释和避免突兀切换，不是持续刺激。总循环约 14 秒：</p><table tabindex="0"><thead><tr><th>时间</th><th>状态</th><th>行为</th></tr></thead><tbody><tr><td>0–2 秒</td><td>暗场建立</td><td>成品低亮度显示轮廓，标题保持可读。</td></tr><tr><td>2–9 秒</td><td>光线揭示</td><td>光线以匀速、低对比度从全屏暗部扫过；经过欧泊时，变彩从局部逐步扩展。使用 <code>linear</code>，不在中段加速。</td></tr><tr><td>9–14 秒</td><td>色彩停留</td><td>保留完整变彩与金属反光约 5 秒后循环。</td></tr></tbody></table><p>首版使用 CSS animation、<code>transform</code>、<code>opacity</code> 和 <code>clip-path</code>，配合本地真实照片实现镜头推进、光线扫掠和色彩显现，不引入动画库。若之后取得合适的真实欧泊视频，只替换媒体层，不改变标题、导航和无障碍接口。</p><p>必须满足：</p><ul><li>光束覆盖全屏，不固定为左侧单根竖线。</li><li>光束恒速移动，亮度和颜色缓慢变化，不制造突然闪烁。</li><li><code>prefers-reduced-motion: reduce</code> 时停留在清晰静态画面。</li><li>不提供额外的重播按钮；普通动效设备进入页面后自动循环，减弱动效设备改为不移动位置的低对比度亮度/色彩呼吸循环。</li><li>hover 动效只在支持精确指针的设备启用，键盘焦点必须立即可见。</li></ul><h2 id="页面与导航" tabindex="-1">页面与导航 <a class="header-anchor" href="#页面与导航" aria-label="Permalink to &quot;页面与导航&quot;">​</a></h2><p>根首页展示欧泊 Hero；主行动入口进入独立中文知识百科入口 <code>/zh/compendium/</code>，英文入口进入 <code>/compendium/</code>，避免与沉浸式 Hero 首页形成回跳。顶部五个模块键复用现有模块路由，不复制模块内容。</p><p>建议组件职责：</p><ul><li><code>GemAtlasLanding.vue</code>：Hero 结构、文案、入口和 reduced-motion 状态。</li><li><code>OpalRevealMedia.vue</code>：素材加载、fallback、光束和变彩揭示层。</li><li><code>ModuleJumpNav.vue</code>：五个模块入口、键盘焦点和移动端滚动。</li></ul><h2 id="加载与无障碍" tabindex="-1">加载与无障碍 <a class="header-anchor" href="#加载与无障碍" aria-label="Permalink to &quot;加载与无障碍&quot;">​</a></h2><ul><li>正式素材本地化，首页不依赖第三方 CDN。</li><li>固定媒体容器比例，避免图片加载造成布局位移。</li><li>图片失败时显示深色展柜背景、标题和知识主页入口。</li><li>若未来使用视频，提供本地 poster、<code>muted</code>、<code>playsInline</code> 和移动端静态降级。</li><li>图片拥有准确 alt，光束和色彩层标记为装饰性内容；普通文本对比度至少 4.5:1。</li><li>五个模块入口是真实链接，拥有清晰焦点环，不只依赖颜色区分。</li></ul><h2 id="验收标准" tabindex="-1">验收标准 <a class="header-anchor" href="#验收标准" aria-label="Permalink to &quot;验收标准&quot;">​</a></h2><ul><li>第一眼主体是欧泊成品，标题位于屏幕中央且保持可读。</li><li>光线约 15 秒匀速扫过全屏，变彩缓慢显现并停留约 5 秒。</li><li>顶部入口编号完整连续为 01–05，桌面端和窄屏均可用。</li><li><code>pnpm validate:data</code>、<code>pnpm generate:pages</code>、<code>pnpm test</code>、<code>pnpm build</code> 通过。</li><li>完成真实浏览器检查：首屏、模块跳转、主入口、键盘焦点、图片失败和 reduced-motion。</li></ul><h2 id="本次不包含" tabindex="-1">本次不包含 <a class="header-anchor" href="#本次不包含" aria-label="Permalink to &quot;本次不包含&quot;">​</a></h2><ul><li>将 VitePress 项目迁移为 React + Tailwind + shadcn。</li><li>在 Hero 内完成欧泊完整教学。</li><li>生成或伪造欧泊内部结构的科学动画。</li><li>未经授权使用商业珠宝品牌或电商素材。</li></ul><h2 id="素材与科学依据" tabindex="-1">素材与科学依据 <a class="header-anchor" href="#素材与科学依据" aria-label="Permalink to &quot;素材与科学依据&quot;">​</a></h2><ul><li><a href="https://commons.wikimedia.org/wiki/File:Rainbow_Shield_Opal_Pendant_Jewelry.jpg" target="_blank" rel="noreferrer">Rainbow Shield Opal Pendant Jewelry</a>，作者 Dpulitzer，CC BY-SA 4.0。</li><li><a href="https://www.gia.edu/opal-description" target="_blank" rel="noreferrer">GIA Opal Description</a>。Hero 动效只做视觉化叙事，科学解释仍以知识页面和可靠资料为准。</li></ul>',26)])])}const m=a(t,[["render",d]]);export{u as __pageData,m as default};
